contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: 1) Put some Ether into c from this contract with specified unlock time and amount;
    // 2) Then attempt Collect for a requested amount and observe whether it reverted; 
    // 3) Assert that if Collect succeeded then c.Acc(address(this)).balance decreased by that amount
    //    and address(c).balance decreased by that amount, and the preconditions (balance>=MinSum, balance>=_am, block.timestamp > unlockTime)
    //    held before Collect.

    // Note: We must send Ether from this contract to c, so require this contract has enough balance.
    function run(uint putUnlock, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "not enough balance to Put");

        // Read account state before any operation (should be zero for fresh c but we treat generally)
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Perform Put sending putAmount wei and provided unlock time
        c.Put{value: putAmount}(putUnlock);

        // Read account state after Put and before Collect
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint cBalMid = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        // Collect is payable in contract but we don't need to send value with Collect
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read account state after Collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // Build the general rule asserted:
        // If Collect did NOT revert then:
        //   1) midBalance >= c.MinSum() and midBalance >= collectAmount and block.timestamp > midUnlock (these are the contract's runtime checks)
        //   2) afterBalance == midBalance - collectAmount
        //   3) c's ether balance decreased by collectAmount
        // If Collect reverted then no requirement about balances is imposed here.

        // We must call c.MinSum() via public getter
        uint minSum = c.MinSum();

        // Compose assertion
        assert(
            reverted || (
                // preconditions held at the time of Collect
                (midBalance >= minSum) && (midBalance >= collectAmount) && (block.timestamp > midUnlock)
                // and balances decreased appropriately
                && (afterBalance + collectAmount == midBalance)
                && (cBalMid == cBalAfter + collectAmount)
            )
        );
    }

    // Allow this test contract to receive Ether so it can call Put
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take putAmount and putUnlock as inputs and send Ether equal to putAmount when calling Put.
    // The rule: if we successfully call Put (did not revert) then the account balance recorded in c for
    // this contract increases by exactly putAmount and the contract's Ether balance increases by putAmount.
    function run(uint putUnlock, uint putAmount) public payable {
        require(address(this).balance >= putAmount, "not enough balance to Put");

        // Read before-values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Perform Put sending putAmount wei and provided unlock time
        bool reverted;
        try c.Put{value: putAmount}(putUnlock) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // If Put succeeded then recorded balance must have increased exactly by putAmount
        // and contract balance must have increased by putAmount. If Put reverted we make no claim.
        assert(reverted || (afterBalance == beforeBalance + putAmount && cBalAfter == cBalBefore + putAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs: collect amount to request, and an optional prior put amount and its unlock time.
    // We first optionally fund the account with putAmount (if >0) so Collect may succeed.
    function run(uint putUnlock, uint putAmount, uint collectAmount) public payable {
        // Ensure the test contract has enough Ether to call Put when needed
        require(address(this).balance >= putAmount, "insufficient balance for Put");

        // Read before-values for this test contract's account and contract balance
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // If caller requested funding, perform Put to set up state (may revert)
        bool putReverted;
        if (putAmount > 0) {
            try c.Put{value: putAmount}(putUnlock) {
                putReverted = false;
            } catch {
                putReverted = true;
            }
        } else {
            putReverted = false; // nothing attempted
        }

        // Read mid-values after Put attempt
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint cBalMid = address(c).balance;

        // Attempt Collect and observe whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // If Collect succeeded, then the account's recorded balance must have decreased by exactly
        // the collected amount, and the contract's Ether balance must have decreased by exactly
        // the same collected amount. If Collect reverted, we make no claim.
        assert(collectReverted || (midBalance >= collectAmount && midBalance - afterBalance == collectAmount && cBalMid >= collectAmount && cBalMid - cBalAfter == collectAmount));
    }

    receive() external payable {}
}

