contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will perform a Put from this contract to c, then attempt Collect, and assert a conservation property
    function run(uint putUnlock, uint putAmount, uint collectAmount) public payable {
        // ensure we have funds to send for Put
        require(address(this).balance >= putAmount);
        // read balances before any operations
        uint before_c_balance = address(c).balance;
        C.Holder memory beforeAcc = c.Acc(address(this));
        uint before_recorded = beforeAcc.balance;

        // perform Put: send putAmount wei and set unlock time
        c.Put{value: putAmount}(putUnlock);

        // read after Put, before Collect
        uint after_put_c_balance = address(c).balance;
        C.Holder memory afterPutAcc = c.Acc(address(this));
        uint after_put_recorded = afterPutAcc.balance;

        // The recorded balance must have increased by putAmount (no overflow due to checks in Put)
        // We don't assert here; we will use values in final general assert.

        // Attempt Collect and record whether it reverted
        bool revertedCollect;
        // To accept ether from c via call, ensure this contract can receive funds (it can via receive())
        try c.Collect(collectAmount) {
            revertedCollect = false;
        } catch {
            revertedCollect = true;
        }

        // read final state after Collect attempt
        uint final_c_balance = address(c).balance;
        C.Holder memory finalAcc = c.Acc(address(this));
        uint final_recorded = finalAcc.balance;

        // compute bookkeeping: total recorded change and on-chain balance change
        uint delta_recorded_afterPut = after_put_recorded - before_recorded; // should equal putAmount
        uint delta_c_afterPut = after_put_c_balance - before_c_balance; // should equal putAmount

        // Final general rule (single assert):
        // 1) After Put, recorded and address(c).balance both increased by putAmount.
        // 2) If Collect did NOT revert, then final_recorded == after_put_recorded - collectAmount
        //    and final_c_balance == after_put_c_balance - collectAmount.
        // 3) If Collect reverted, final values equal the after-Put values (no change from Collect).
        assert(
            // condition 1
            (delta_recorded_afterPut == putAmount && delta_c_afterPut == putAmount)
            &&
            // condition 2 or 3
            (
                (!revertedCollect && final_recorded + collectAmount == after_put_recorded && final_c_balance + collectAmount == after_put_c_balance)
                ||
                (revertedCollect && final_recorded == after_put_recorded && final_c_balance == after_put_c_balance)
            )
        );
    }

    // allow receiving Ether from c during Collect
    receive() external payable {}
}

