contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We perform one Put (sending putAmount wei) then attempt Collect(collectAmount).
    // Assert that if Collect succeeded then recorded balance decreased by collectAmount and
    // this contract's balance increased by collectAmount; otherwise both stayed the same.
    function run(uint putUnlock, uint putAmount, uint collectAmount) public payable {
        // ensure this test contract has enough Ether to fund Put
        require(address(this).balance >= putAmount);

        // read recorded holder info before any action
        (uint before_unlock, uint before_recorded) = c.Acc(address(this));
        uint before_wallet = address(this).balance;

        // perform Put: send putAmount wei
        c.Put{value: putAmount}(putUnlock);

        // read after-put recorded balance and this contract balance
        (uint after_put_unlock, uint after_put_recorded) = c.Acc(address(this));
        uint after_put_wallet = address(this).balance;

        // Attempt Collect and record whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read final recorded balance and this contract balance
        (uint final_unlock, uint final_recorded) = c.Acc(address(this));
        uint final_wallet = address(this).balance;

        // Single assert expressing the property:
        // - Put may change recorded and wallet balances in some way; we only require
        //   that Collect, if it succeeded, transfers exactly collectAmount from c to this contract
        //   and reduces the recorded balance by exactly collectAmount; if it reverted then
        //   neither recorded balance nor wallet balance changed by the Collect attempt.
        assert(
            (
                // Collect succeeded: recorded decreases by collectAmount and wallet increases by collectAmount
                (!collectReverted)
                && final_recorded + collectAmount == after_put_recorded
                && final_wallet == after_put_wallet + collectAmount
            )
            ||
            (
                // Collect reverted: recorded and wallet unchanged since after_put
                (collectReverted)
                && final_recorded == after_put_recorded
                && final_wallet == after_put_wallet
            )
        );
    }

    // allow receiving Ether from c during Collect
    receive() external payable {}
}

