contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test interplay of Put and Collect for this contract instance (msg.sender is this contract)
    // Inputs:
    //  putValue - amount of ETH to send to Put (or via fallback if useFallback true)
    //  unlockTime - parameter to Put
    //  collectAmt - amount to attempt to collect
    //  useFallback - if true call fallback by sending value with no data, else call Put
    function run(uint putValue, uint unlockTime, uint collectAmt, bool useFallback) public payable {
        require(address(this).balance >= putValue + 1 wei);
        // Snapshot observable state before operations
        uint beforeHolderBal = c.Acc(address(this)).balance;
        uint beforeContractBal = address(c).balance;

        // Call Put (or fallback) sending putValue
        if (useFallback) {
            // fallback() calls Put(0) inside contract
            c.f{value: putValue}();
        } else {
            c.Put{value: putValue}(unlockTime);
        }

        // After Put, read state
        uint afterHolderBal = c.Acc(address(this)).balance;
        uint afterContractBal = address(c).balance;

        // Try Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read values after Collect attempt
        uint finalHolderBal = c.Acc(address(this)).balance;
        uint finalContractBal = address(c).balance;

        // Assertions (single assert combining the intended invariants):
        // 1) Put never decreases the stored balance: afterHolderBal >= beforeHolderBal
        // 2) Contract balance increases by at most putValue: (afterContractBal - beforeContractBal) <= putValue
        // 3) If Collect succeeded then finalHolderBal = afterHolderBal - collectAmt and finalContractBal = afterContractBal - collectAmt
        // 4) If Collect reverted then balances remain unchanged: finalHolderBal == afterHolderBal && finalContractBal == afterContractBal
        assert(
            afterHolderBal >= beforeHolderBal
            && (afterContractBal >= beforeContractBal && (afterContractBal - beforeContractBal) <= putValue)
            && (
                (!collectReverted && finalHolderBal + collectAmt == afterHolderBal && finalContractBal + collectAmt == afterContractBal)
                || (collectReverted && finalHolderBal == afterHolderBal && finalContractBal == afterContractBal)
            )
        );
    }

    // allow receiving ETH to fund tests
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Inputs:
    // putValue - amount of ETH to send with Put (or via fallback)
    // unlockTime - parameter to Put
    // collectAmt - amount to attempt to Collect
    // useFallback - if true, call fallback by invoking c with empty calldata
    function run(uint putValue, uint unlockTime, uint collectAmt, bool useFallback) public payable {
        // Need ETH to send for Put if requested
        require(address(this).balance >= putValue, "insufficient balance for putValue");

        // Snapshot observable state before operations
        (uint beforeUnlock, uint beforeHolderBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Call Put (or fallback) sending putValue
        if (useFallback) {
            // fallback forwards to Put(0) inside contract
            // call with empty calldata
            (bool ok,) = address(c).call{value: putValue}("");
            require(ok, "fallback call failed");
        } else {
            c.Put{value: putValue}(unlockTime);
        }

        // After Put, read state
        (, uint afterHolderBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Try Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read values after Collect attempt
        (, uint finalHolderBal) = c.Acc(address(this));
        uint finalContractBal = address(c).balance;

        // Assertion combining invariants:
        // 1) Put never decreases the stored balance
        // 2) Contract balance increases by at most putValue
        // 3) If Collect succeeded then finalHolderBal = afterHolderBal - collectAmt and finalContractBal = afterContractBal - collectAmt
        // 4) If Collect reverted then balances unchanged
        assert(
            // 1 and 2
            afterHolderBal >= beforeHolderBal
            && afterContractBal >= beforeContractBal
            && (afterContractBal - beforeContractBal) <= putValue
            // 3 or 4
            && (
                (!collectReverted
                    && finalHolderBal + collectAmt == afterHolderBal
                    && finalContractBal + collectAmt == afterContractBal)
                || (collectReverted
                    && finalHolderBal == afterHolderBal
                    && finalContractBal == afterContractBal)
            )
        );
    }

    // allow receiving ETH to fund tests
    receive() external payable {}
}

