            c.Put{value: putValue}(0);
        } else {
            c.Put{value: putValue}(unlockTime);
        }

        // Read observable state after Put/fallback
        (, uint afterHolderBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read observable state after Collect attempt
        (, uint finalHolderBal) = c.Acc(address(this));
        uint finalContractBal = address(c).balance;

        // Assert the general rule:
        // 1) afterHolderBal >= beforeHolderBal  (Put never decreases stored balance)
        // 2) afterContractBal >= beforeContractBal and (afterContractBal - beforeContractBal) <= putValue
        // 3) If Collect succeeded then finalHolderBal + collectAmt == afterHolderBal AND finalContractBal + collectAmt == afterContractBal
        // 4) If Collect reverted then finalHolderBal == afterHolderBal AND finalContractBal == afterContractBal
        assert(
            afterHolderBal >= beforeHolderBal
            && afterContractBal >= beforeContractBal
            && (afterContractBal - beforeContractBal) <= putValue
            && (
                (!collectReverted
                    && finalHolderBal + collectAmt == afterHolderBal
                    && finalContractBal + collectAmt == afterContractBal)
                || (collectReverted
                    && finalHolderBal == afterHolderBal
                    && finalContractBal == afterContractBal)
            )
        );
    }

    // allow receiving ETH to fund tests
    receive() external payable {}
}

contract InvMutTest {
