contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters to drive Put and Collect. amountPut funds the contract for msg.sender (this test contract)
    // collectAmt is the requested amount to collect. unlock sets unlock time for Put.
    // We will first Put some value, then try Collect and observe effects.
    function run(uint amountPut, uint collectAmt, uint unlock) public payable {
        // ensure this contract has enough Ether to forward amountPut when calling Put
        require(address(this).balance >= amountPut);
        // record before values observable from c for this test contract (msg.sender for c calls will be this contract)
        // read prior stored balance and contract balance
        uint beforeHolderBalance = c.Acc(address(this)).balance;
        uint beforeContractBalance = address(c).balance;

        // perform Put to deposit amountPut and set unlock time
        c.Put{value: amountPut}(unlock);

        // read after-put values
        uint afterPutHolderBalance = c.Acc(address(this)).balance;
        uint afterPutContractBalance = address(c).balance;

        // basic sanity: after Put the holder's balance must have increased by amountPut (or at least not decreased)
        // We'll capture prior to Collect state
        uint priorBalance = afterPutHolderBalance;
        uint priorContractBal = afterPutContractBalance;

        // Now attempt Collect(collectAmt) catching revert
        bool reverted;
        // We must call Collect as a top-level statement
        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-Collect observable values
        uint postBalance = c.Acc(address(this)).balance;
        uint postContractBal = address(c).balance;

        // The general rule to assert:
        // - If Collect did not revert, then priorBalance >= collectAmt and priorBalance >= c.MinSum() and block.timestamp > prior unlockTime must have held, and balances decreased by collectAmt.
        // - If Collect reverted, then balances remain equal to prior values.
        // We cannot directly read unlockTime or block.timestamp relation in a single expression without calling acc.unlockTime (it's public via Acc mapping -> struct fields are accessible), but Acc(...).unlockTime is readable because Acc is public mapping returning Holder struct via getter. Use those.

        // Build condition: either reverted and no change, or not reverted and decrease exactly by collectAmt
        // Note: avoid underflow in expressions inside assert by comparing with >= first.
        bool noChangeIfReverted = reverted && postBalance == priorBalance && postContractBal == priorContractBal;

        // When not reverted: postBalance == priorBalance - collectAmt and postContractBal == priorContractBal - collectAmt
        // Also require that priorBalance >= collectAmt and priorBalance >= c.MinSum() and block.timestamp > priorUnlock
        uint priorUnlock = c.Acc(address(this)).unlockTime;
        uint minSum = c.MinSum();
        bool validCollectPreconds = priorBalance >= collectAmt && priorBalance >= minSum && block.timestamp > priorUnlock;
        bool effectIfNotReverted = (!reverted) && postBalance + collectAmt == priorBalance && postContractBal + collectAmt == priorContractBal && validCollectPreconds;

        assert(noChangeIfReverted || effectIfNotReverted);
    }

    // receive to accept refunds if any
    receive() external payable {}
}

