        }

        // observe after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Put reverted then nothing observable changed.
        // If Put returned (did not revert) then stored balance and contract balance both increased by exactly amount
        // and unlockTime is set to at least block.timestamp (observed as >= beforeUnlock or >= block.timestamp)
        // We cannot read block.timestamp at assertion time reliably, so require that afterUnlock >= beforeUnlock.
        assert(
            (putReverted && afterBal == beforeBal && afterContractBal == beforeContractBal && afterUnlock == beforeUnlock)
            || (!putReverted && afterBal == beforeBal + amount && afterContractBal == beforeContractBal + amount && afterUnlock >= beforeUnlock)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We use amount and unlock to drive Put; callViaFallback selects whether to call fallback()
    function run(uint amount, uint unlock, bool callViaFallback) public payable {
        require(address(this).balance >= amount);
        // Read before-values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        bool reverted = false;
        if (callViaFallback) {
            // fallback will call Put(0)
            try c.f{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.Put{value: amount}(unlock) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // If the call reverted, observable state must be unchanged (no balance or contract balance increase).
        // If it did not revert, the recorded balance must have increased by at least amount and contract balance increases exactly by amount.
        assert(reverted ? (afterBalance == beforeBalance && cBalAfter == cBalBefore && afterUnlock == beforeUnlock)
                        : (afterBalance >= beforeBalance + amount && cBalAfter == cBalBefore + amount));
    }

    // Allow receiving refunds from C when Collect is invoked
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run attempts to Collect an amount _am; must fund c first so Collect can succeed in some cases.
    // params: fund — amount to put into c before Collect; unlock — unlock time to set when funding; am — amount to attempt to collect
    function run(uint fund, uint unlock, uint am) public payable {
        // Ensure this test contract has enough balance to fund c
        require(address(this).balance >= fund);

        // Read before-values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        // Fund c by calling Put (use Put directly). If fund == 0 this is a no-op but still a call.
        bool putReverted = false;
        try c.Put{value: fund}(unlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Now attempt Collect of amount am. Capture whether it reverted.
        bool collectReverted = true;
        try c.Collect{value: 0}(am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;
        uint selfBalAfter = address(this).balance;

        // General rule:
        // If Collect did not revert then:
        //  - the recorded balance decreased by exactly am (afterBalance + am == balance before the collect call that succeeded)
        //  - C's ether balance decreased by exactly am
        //  - this contract's balance increased by exactly am
        // If Collect reverted then no guarantees about balances are required beyond consistent observable states;
        // however we must ensure the assert is a general relation over observed values and params.
        assert(
            collectReverted || (
                // collect succeeded
                // recorded balance decreased by exactly am (avoid underflow by comparing sums)
                afterBalance + am == (putReverted ? beforeBalance : (beforeBalance + fund))
                // C's balance decreased by exactly am
                && cBalAfter + am == cBalBefore + (putReverted ? 0 : fund)
                // this contract's balance increased by exactly am (it may have decreased by fund earlier)
                && selfBalAfter == selfBalBefore - (putReverted ? 0 : fund) + am
            )
        );
    }

    // allow receiving Ether when Collect sends funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // fund: amount of wei to send to c via Put
    // unlock: unlock time to set when funding
    // am: amount to attempt to Collect
    function run(uint fund, uint unlock, uint am) public payable {
        require(address(this).balance >= fund);

        // Observe before state
        (uint beforeUnlock, uint beforeRecorded) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        // Fund c by calling Put (may revert)
        bool putReverted = false;
        try c.Put{value: fund}(unlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe recorded balance after Put (or failed Put)
        (uint midUnlock, uint midRecorded) = c.Acc(address(this));
        uint cBalMid = address(c).balance;
        uint selfBalMid = address(this).balance;

        // Attempt Collect and record whether it reverted
        bool collectReverted = true;
        try c.Collect{value: 0}(am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe after-values
        (uint afterUnlock, uint afterRecorded) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;
        uint selfBalAfter = address(this).balance;

        // General rule:
        // If Collect succeeded then:
        //  - the recorded balance decreased (afterRecorded <= midRecorded)
        //  - C's ether balance decreased by the same amount as the recorded balance decreased
        //    (i.e., (midRecorded - afterRecorded) == (cBalMid - cBalAfter))
        // We express decrease using non-negative differences to avoid underflow in the assert.
        assert(
            collectReverted || (
                // recorded balance did not increase
                afterRecorded <= midRecorded
                // the drop in recorded balance equals the drop in contract Ether balance
                && (midRecorded - afterRecorded) == (cBalMid - cBalAfter)
            )
        );
    }

    // Receive any Ether sent by C during Collect
    receive() external payable {}
}
